const savedLanguage = localStorage.getItem('taxilux-language')

i18n.use(initReactI18next).init({
  resources: { fr: { translation: {} }, nl: { translation: nl }, en: { translation: en } },
  lng: savedLanguage && ['fr', 'nl', 'en'].includes(savedLanguage) ? savedLanguage : 'fr',
  fallbackLng: 'fr',
  keySeparator: false,
  interpolation: { escapeValue: false },
})

export default i18n
